@MainActor func transient_ComponentInProject_componentPadDictionary (
       _ self_mX : CanariLength,                                     
       _ self_mY : CanariLength,                                     
       _ self_mRotation : CanariAngle,                               
       _ self_mSide : ComponentSide,                                 
       _ self_packagePadDictionary : PackageMasterPadDictionary
) -> ComponentPadDescriptorDictionary {
//--- START OF USER ZONE 2
        var af = CanariAffinity.translating (x: self_mX, y: self_mY).rotating (by: self_mRotation)
        if self_mSide == .back {
          af.scale (x: -1.0, y: 1.0)
        }
        let center = self_packagePadDictionary.padsRect.center
        af.translate (x: -center.x, y: -center.y)
        var result = ComponentPadDescriptorDictionary ()
        for (padName, descriptor) in self_packagePadDictionary {
          let padSide : ConnectorSide
          switch descriptor.style {
          case .traversing :
            padSide = .traversing
          case .surface :
            switch self_mSide {
            case .back :
              padSide = .back
            case .front :
              padSide = .front
            }
          }
          let p = PadLocationAndSide (
            location: af.transforming (descriptor.center),
            side: padSide
          )
          var pads = [p]
          for slavePad in descriptor.slavePads {
            let padSide : ConnectorSide
            switch slavePad.style {
            case .traversing :
              padSide = .traversing
            case .oppositeSide :
              switch self_mSide {
              case .back :
                padSide = .front
              case .front :
                padSide = .back
              }
            case .componentSide :
              switch self_mSide {
              case .back :
                padSide = .back
              case .front :
                padSide = .front
              }
            }
            let p = PadLocationAndSide (
              location: af.transforming (slavePad.center),
              side: padSide
            )
            pads.append (p)
          }
          let d = ComponentPadDescriptor (padName: padName, pads: pads)
          result [padName] = d
        }
        return result
//--- END OF USER ZONE 2
}

